import openpyxl
wb = openpyxl.load_workbook('seed_collection_0062_inconsistent_color_9486_input.xlsx')
for ws in wb.worksheets:
    print('SHEET', ws.title, ws.dimensions)
    fills = {}
    fonts = {}
    for row in ws.iter_rows():
        for c in row:
            fill = c.fill
            if fill is not None and fill.patternType is not None:
                key = (fill.patternType, fill.fgColor.rgb, fill.bgColor.rgb)
                fills.setdefault(key, []).append(c.coordinate)
            font = c.font
            if font is not None and font.color is not None:
                key = (font.color.rgb, font.bold, font.italic)
                fonts.setdefault(key, []).append(c.coordinate)
    print('fills:')
    for k,v in fills.items():
        print(k, len(v), v[:50])
    print('fonts:')
    for k,v in fonts.items():
        print(k, len(v), v[:100])
    print()
